-- supabase/migrations/20260923000000_dirt_routes_between_bridges.sql
-- ─────────────────────────────────────────────────────────────────────────────
-- Map-riders: снести старые маршруты, засеять грунтовые «между мостами».
--
-- «Ditch old routes from map and investigate how to create new ones (dirt bike
-- routes inbetween bridges along river nearby)» — map-riders, 2026-09-23.
--
-- Что делает:
--   1. Убирает из points_of_interest старые сид-треки ПО ИМЕНИ:
--      «Федоровского → Сормово → Москва ш.» (vip-fedorovsky-sormovo-loop),
--      «city center» (route-dd05b5ca…), «Off-road» (route-138f5c07…)
--      и устаревшие демо-точки vip-demo-rider-a/b/c (клиент их уже фильтрует).
--      Точечные POI (HQ и т.п.) и маршруты, созданные админом через
--      /admin/map-routes (route-<uuid>), НЕ трогаются.
--   2. Добавляет 3 грунтовых маршрута вдоль Оки между реальными мостами.
--      Геометрия: реальные сходы мостов (OSM ways 168040093, 108685019,
--      27804831) + осевая линия Оки (OSM relation 163223) со смещением к
--      выбранному берегу ~100–150 м, сглаживание Catmull-Rom
--      (скрипт scripts/gen_dirt_routes.py в репо-патче).
--
-- Идемпотентно: перезапуск пересобирает тот же список — dirt-* пересеиваются,
-- все точечные POI и админские маршруты (route-*, /admin/map-routes) живут.
-- ⚠️ Применять вручную в SQL editor (Supabase dashboard), как обычно.
-- ─────────────────────────────────────────────────────────────────────────────

begin;

with target_map as (
  select id
  from public.maps
  order by
    case
      when lower(coalesce(metadata->>'crew_slug', metadata->>'crewSlug', metadata->>'slug', '')) = 'vip-bike' then 0
      when is_default then 1
      else 2
    end,
    created_at desc
  limit 1
),
-- Держим точечные POI + админские маршруты (route-* — их создает
-- /admin/map-routes, сносить молча нельзя), затем добавляем грунтовые треки.
-- Старые сид-маршруты удаляем ПО ИМЕНИ (vip-fedorovsky-sormovo-loop и два
-- route-<uuid> из сид-скрипта) — «снести все не-point» было бы ловушкой для
-- маршрутов, созданных админом позже. Демо-райдеры тоже уходят.
kept_points as (
  select m.id as map_id,
         coalesce(jsonb_agg(poi), '[]'::jsonb) as keep_pois
  from public.maps m
  join target_map t on t.id = m.id
  left join lateral jsonb_array_elements(coalesce(m.points_of_interest, '[]'::jsonb)) poi on true
  where (
          coalesce(poi->>'type', 'point') = 'point'
          or coalesce(poi->>'id', '') like 'route-%'   -- админские маршруты живут
        )
    and coalesce(poi->>'id', '') not like 'vip-demo-rider-%'
    and coalesce(poi->>'id', '') not in (
          'vip-fedorovsky-sormovo-loop',                        -- старый асфальтовый луп
          'route-dd05b5ca-2013-43ad-a80f-534fc7147015',         -- старый «city center»
          'route-138f5c07-3743-44d5-ad60-2aeca537f5ba'          -- старый «Off-road»
        )
  group by m.id
),
dirt_routes as (
  select jsonb_build_array(
