  ) as routes
),
merged as (
  select k.map_id,
         k.keep_pois || d.routes as next_pois
  from kept_points k
  cross join dirt_routes d
)
update public.maps m
set points_of_interest = mg.next_pois
from merged mg
where m.id = mg.map_id;

commit;
